        // Spec says: "asynchronously reset into state B if reset if high"
        // State B output is 1 according to the diagram: B (1)
        if (out !== 1'b1) begin
            $display("Time %0t: Async reset fail! Expected out=1 for state B, got %b", $time, out);
            errors = errors + 1;
