        // Diagram:
        // B (1) --0--> A (0)
        // B (1) --1--> B (1)

        @(posedge clk);
        in = 1'b1; // B --1--> B
        check_output(1'b1);

        @(posedge clk);
        in = 1'b0; // B --0--> A
        check_output(1'b0); // State A output is 0

