        // Diagram:
        // A (0) --0--> B (1)
        // A (0) --1--> A (0)

        @(posedge clk);
        in = 1'b1; // A --1--> A
        check_output(1'b0);

        @(posedge clk);
        in = 1'b0; // A --0--> B
        check_output(1'b1);

        // 4. Test asynchronous reset override during operation
        @(posedge clk);
        in = 1'b0; // currently in B, 0 goes to A
        #1;
        areset = 1; // Assert reset asynchronously
        #1;
        if (out !== 1'b1) begin
            $display("Time %0t: Async reset during operation fail! Expected out=1, got %b", $time, out);
            errors = errors + 1;
        end
        areset = 0;
        #3;

        // Final Result Evaluation
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
